---特训Boss
function OverseaClubBossInfoNode:RefreshBigBoss(data,isNext)
    self.bossData = data
    self.bossType = ClubUtils.BossType.BigBoss
    self.isNext = isNext
    self:FillCommonInfo(isNext)

    if not isNext then
        local isBossNoDie = self.bossData.remainingHp > 0
        if isBossNoDie then
            local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
            local isAllSmallBossDie = bossDojo:IsAllSmallBossDie()
            CfUtils.SetActive(self.ImgLockMask1.gameObject,not isAllSmallBossDie)
            CfUtils.SetActive(self.ImgLockMask2.gameObject,not isAllSmallBossDie)
            CfUtils.SetActive(self.ImgLockMask3.gameObject,not isAllSmallBossDie)

            local isHaveNum = bossDojo:GetBossAtNumByQuestId(self.bossData.questId)
            CfUtils.SetActive(self.InCombat.gameObject,isHaveNum > 0)
        else
            CfUtils.SetActive(self.DeadRoot.gameObject,true)
        end
    else
        CfUtils.SetActive(self.DeadRoot.gameObject,false)
        CfUtils.SetActive(self.ImgLockMask1.gameObject,false)
        CfUtils.SetActive(self.ImgLockMask2.gameObject,false)
        CfUtils.SetActive(self.ImgLockMask3.gameObject,false)
    end
end

function OverseaClubBossInfoNode:FillCommonInfo(isNext)
    CfUtils.SetActive(self.InCombat.gameObject,false)
    local bossData = self:GetBossData(self.bossData.questId)
    for i, v in pairs(bossData) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                self.bossId = v.wave1NpcId[k]
                CfUtils.SetUISwitchImage(self.ImgAttribute,checkNumber(v.attribute[k]))
            end
        end
    end
    if not isNull(self.bossId) then
        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(self.bossId)
        if not isNull(monster) then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monster.skinId)
            if not isNull(skinVo) then
                CfUtils.FillImage(self.ImgHead,skinVo.buffHead)
            end
        end
    end
    CfUtils.SetUISwitchImage(self.ImgFill,self.bossType)
    if isNext then
        self.ImgFill.fillAmount = 1
    else
        self.ImgFill.fillAmount = self.bossData.remainingHp/self.bossData.totalHp
        CfUtils.FillText(self.TextNumber,string.format("%.2f",self.bossData.remainingHp/self.bossData.totalHp * 100)  .."%")
    end
    local aniName = isNext and "OverseaClubBossMainDialog_BossInfo_NumberClose" or "OverseaClubBossMainDialog_BossInfo_NumberOpen"
    CfUtils.PlayAnimation(self.ProgressNumber,aniName)
end

function OverseaClubBossInfoNode:GetBossData(id)
    return QuestConfMgr:GetInstance():GetAllQuestLineupVo(id)
end

---小Boss
function OverseaClubBossInfoNode:RefreshBoss(data,isNext)
    self.bossData = data
    self.bossType = ClubUtils.BossType.NormalBoss
    self.isNext = isNext
    self:FillCommonInfo(isNext)

    if not isNext then
        local isBossNoDie = self.bossData.remainingHp > 0
        CfUtils.SetActive(self.DeadRoot.gameObject,not isBossNoDie)
        if isBossNoDie then
            local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
            local isHaveNum = bossDojo:GetBossAtNumByQuestId(self.bossData.questId)
            CfUtils.SetActive(self.InCombat.gameObject,isHaveNum > 0)
        end
    end
end

function OverseaClubBossInfoNode:RefreshSelect(index)
    if self.index == index then
        self:OnBtnNodeClick()
    end
end

function OverseaClubBossInfoNode:OnBtnNodeClick()
    if self.isNext then
        return
    end

    if self.bossType == ClubUtils.BossType.NormalBoss then
        self:SetSelectRootState(true)
        if not isNull(self.callBack) then
            self.callBack(self.index,self.bossData)
        end
    else
        local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
        local isAllSmallBossDie = bossDojo:IsAllSmallBossDie()
        if isAllSmallBossDie then
            self:SetSelectRootState(true)
            if not isNull(self.callBack) then
                self.callBack(self.index,self.bossData)
            end
        else
            GameUtils.Toast(localize("特级讨伐暂未解锁，请先通关普通讨伐"))
        end
    end
end

function OverseaClubBossInfoNode:DoSelect()
    self:SetSelectRootState(false)
end

function OverseaClubBossInfoNode:SetSelectRootState(status)
    KTool.SetActive(self.SelectRoot.gameObject,status)
end

function OverseaClubBossInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaClubBossInfoNode